import { Stream } from 'node:stream'

function isReadable(stream) {
  return stream instanceof Stream.Readable || typeof stream?.pipe === 'function'
}

function currentDestinations(stream) {
  const state = stream?._readableState
  if (!state || !state.pipes) return []
  return Array.isArray(state.pipes) ? state.pipes.slice() : [state.pipes]
}

export function unpipeAll(stream) {
  if (!isReadable(stream) || typeof stream.unpipe !== 'function') {
    throw new TypeError('unpipeAll expects a readable stream')
  }

  const detached = []
  const seen = new Set()

  for (let destinations = currentDestinations(stream); destinations.length > 0; destinations = currentDestinations(stream)) {
    for (const destination of destinations) {
      if (seen.has(destination)) continue
      seen.add(destination)
      stream.unpipe(destination)
      detached.push(destination)
    }
    if (destinations.every((d) => seen.has(d))) {
      // safety: also try the no-arg form which detaches everything
      stream.unpipe()
      break
    }
  }

  const remaining = currentDestinations(stream)
  if (remaining.length > 0) {
    throw new Error(`unpipeAll could not detach ${remaining.length} destination(s)`)
  }

  if (typeof stream.pause === 'function' && stream.readableFlowing !== false) {
    stream.pause()
  }

  return detached
}
```

