import { Stream } from 'node:stream'

const hasUnpipe = (value) =>
  value !== null && typeof value === 'object' && typeof value.unpipe === 'function'

const hasPipe = (value) =>
  value !== null && typeof value === 'object' && typeof value.pipe === 'function'

function destinationsOf(stream) {
  const state = stream._readableState
  if (!state || !state.pipes) return []
  const pipes = state.pipes
  return Array.isArray(pipes) ? pipes.slice() : [pipes]
}

export function unpipeAll(stream) {
