    throw new TypeError('unpipeAll expects a readable stream with an unpipe() method')
  }

  const destinations = destinationsOf(stream)

  for (const destination of destinations) {
    stream.unpipe(destination)
  }

  stream.unpipe()

  const remaining = destinationsOf(stream)
  if (remaining.length > 0) {
    throw new Error(`unpipeAll was unable to detach ${remaining.length} destination(s)`)
  }

  if (typeof stream.pause === 'function') {
    stream.pause()
  }

  return destinations
}

